  else if (o.repite === true) texto = '¡Claro! 😊 Aquí tienes otra vez el botón para escribirle directo a ' + quien + (o.pideEmpresa ? '. Y para dejarlo anotado, ¿cómo se llama tu negocio? 😊' : '.');
  else {
